package com.usermonitor.server.service;

import com.usermonitor.server.dto.Requests;
import com.usermonitor.server.model.*;
import com.usermonitor.server.repository.*;
import lombok.RequiredArgsConstructor;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.security.SecureRandom;
import java.time.*;
import java.util.*;

@Service @RequiredArgsConstructor
public class LicenseService {
 private static final char[] CHARS="ABCDEFGHJKLMNPQRSTUVWXYZ23456789".toCharArray();
 private static final SecureRandom RNG=new SecureRandom();
 private final LicenseRepository licenses;private final DeviceRepository devices;private final ClientSessionRepository sessions;private final MonitoredDeviceRepository monitoredDevices;private final RuntimeConfigRepository runtimeConfigs;
 @Value("${app.session-hours}") private long sessionHours;
 @Transactional public List<LicenseKey> generate(Requests.GenerateKeys r){List<LicenseKey> out=new ArrayList<>();String prefix=r.prefix()==null?"":r.prefix().trim().toUpperCase(Locale.ROOT);String custom=r.customCode()==null?"":r.customCode().trim().toUpperCase(Locale.ROOT);if(!custom.isBlank()&&r.count()!=1)throw new IllegalArgumentException("自定义卡密只能单码创建");if(!custom.isBlank()&&licenses.findByCode(custom).isPresent())throw new IllegalArgumentException("自定义卡密已存在");for(int i=0;i<r.count();i++){LicenseKey k=new LicenseKey();k.setCode(custom.isBlank()?uniqueCode(prefix):custom);k.setDurationDays(r.durationDays());k.setMaxDevices(r.maxDevices());k.setMaxUses(r.maxUses()==null?0:r.maxUses());k.setDeviceBindingEnabled(r.deviceBindingEnabled()==null||r.deviceBindingEnabled());k.setDeviceVerificationEnabled(r.deviceVerificationEnabled()==null||r.deviceVerificationEnabled());k.setRemark(r.remark());out.add(k);}return licenses.saveAll(out);}
 @Transactional public boolean validateCard(String code,String deviceCode){if(!validationEnabled())return !code.trim().isEmpty();LicenseKey k=licenses.findByCode(code.trim().toUpperCase(Locale.ROOT)).orElseThrow(()->new IllegalArgumentException("卡密不存在"));LocalDateTime now=LocalDateTime.now();if(k.getStatus()==LicenseKey.Status.DISABLED)throw new IllegalArgumentException("卡密已禁用");if(k.getExpiresAt()!=null&&!k.getExpiresAt().isAfter(now))throw new IllegalArgumentException("卡密已过期");if(k.isDeviceVerificationEnabled())requireEnabledMonitoredDevice(deviceCode);if(k.getMaxUses()>0&&k.getUsedCount()>=k.getMaxUses())throw new IllegalArgumentException("卡密使用次数已用完");k.setUsedCount(k.getUsedCount()+1);licenses.save(k);if(k.getStatus()==LicenseKey.Status.UNUSED){k.setStatus(LicenseKey.Status.ACTIVE);k.setActivatedAt(now);k.setExpiresAt(now.plusDays(k.getDurationDays()));licenses.save(k);}return true;}
 @Transactional public boolean registerAndCheckDevice(String deviceCode,String deviceName,String ip){MonitoredDevice d=monitoredDevices.findByDeviceCode(deviceCode).orElseGet(()->{MonitoredDevice n=new MonitoredDevice();n.setDeviceCode(deviceCode);n.setEnabled(false);return n;});d.setDeviceName(deviceName);d.setLastSeenAt(LocalDateTime.now());d.setLastIp(ip);monitoredDevices.save(d);return d.isEnabled();}
 public boolean isDeviceEnabled(String code){return monitoredDevices.findByDeviceCode(code).map(MonitoredDevice::isEnabled).orElse(false);}
 private void requireEnabledMonitoredDevice(String code){if(!isDeviceEnabled(code))throw new IllegalArgumentException("云端设备码未启用");}
 @Transactional public Map<String,Object> clientLogin(Requests.ClientLogin r,String ip){if(!validationEnabled())return Map.of("bypass",true,"token","","expiresAt",LocalDateTime.now().plusYears(10).toString(),"licenseExpiresAt",LocalDateTime.now().plusYears(10).toString(),"deviceId",0);LicenseKey key=licenses.findByCode(r.licenseKey().trim().toUpperCase(Locale.ROOT)).orElseThrow(()->new IllegalArgumentException("卡密不存在"));LocalDateTime now=LocalDateTime.now();if(key.getStatus()==LicenseKey.Status.DISABLED)throw new IllegalArgumentException("卡密已禁用");if(key.getExpiresAt()!=null&&!key.getExpiresAt().isAfter(now)){key.setStatus(LicenseKey.Status.EXPIRED);licenses.save(key);throw new IllegalArgumentException("卡密已过期");}Device device=key.isDeviceBindingEnabled()?devices.findByLicenseAndDeviceCode(key,r.deviceCode()).orElse(null):null;if(device==null){if(devices.countByLicenseAndEnabledTrue(key)>=key.getMaxDevices())throw new IllegalArgumentException("设备绑定数量已达上限");device=new Device();device.setLicense(key);device.setDeviceCode(r.deviceCode());device.setDeviceName(r.deviceName());device.setEnabled(true);}else if(!device.isEnabled())throw new IllegalArgumentException("设备已被禁用");if(key.getStatus()==LicenseKey.Status.UNUSED){key.setStatus(LicenseKey.Status.ACTIVE);key.setActivatedAt(now);key.setExpiresAt(now.plusDays(key.getDurationDays()));licenses.save(key);}device.setLastSeenAt(now);device.setLastIp(ip);device=devices.save(device);ClientSession session=new ClientSession();session.setDevice(device);session.setToken(randomHex(32));session.setExpiresAt(now.plusHours(sessionHours));sessions.save(session);return Map.of("token",session.getToken(),"expiresAt",session.getExpiresAt().toString(),"licenseExpiresAt",key.getExpiresAt().toString(),"deviceId",device.getId());}
 @Transactional public Map<String,Object> heartbeat(String token,String ip){if(!validationEnabled())return Map.of("valid",true,"serverTime",LocalDateTime.now().toString());ClientSession s=sessions.findByTokenAndRevokedFalse(token).orElseThrow(()->new IllegalArgumentException("会话无效"));LocalDateTime now=LocalDateTime.now();if(!s.getExpiresAt().isAfter(now)||!s.getDevice().isEnabled())throw new IllegalArgumentException("授权已失效");LicenseKey k=s.getDevice().getLicense();if(k.getStatus()!=LicenseKey.Status.ACTIVE||!k.getExpiresAt().isAfter(now))throw new IllegalArgumentException("卡密已失效");s.setLastHeartbeatAt(now);s.getDevice().setLastSeenAt(now);s.getDevice().setLastIp(ip);sessions.save(s);devices.save(s.getDevice());return Map.of("valid",true,"serverTime",now.toString(),"licenseExpiresAt",k.getExpiresAt().toString());}
 @Transactional public void setLicenseStatus(long id,LicenseKey.Status status){LicenseKey k=licenses.findById(id).orElseThrow(()->new IllegalArgumentException("卡密不存在"));k.setStatus(status);licenses.save(k);}
 @Transactional public LicenseKey updateLicense(long id,Requests.LicenseUpdate r){LicenseKey k=licenses.findById(id).orElseThrow(()->new IllegalArgumentException("卡密不存在"));if(r.durationDays()!=null)k.setDurationDays(r.durationDays());if(r.maxDevices()!=null)k.setMaxDevices(r.maxDevices());if(r.maxUses()!=null)k.setMaxUses(r.maxUses());if(r.deviceBindingEnabled()!=null)k.setDeviceBindingEnabled(r.deviceBindingEnabled());if(r.deviceVerificationEnabled()!=null)k.setDeviceVerificationEnabled(r.deviceVerificationEnabled());if(r.expiresAt()!=null){k.setExpiresAt(r.expiresAt());k.setStatus(r.expiresAt().isAfter(LocalDateTime.now())?LicenseKey.Status.ACTIVE:LicenseKey.Status.EXPIRED);}if(r.remark()!=null)k.setRemark(r.remark().trim());return licenses.save(k);}
 @Transactional public Device rebindDevice(long id,Requests.DeviceRebind r){Device d=devices.findById(id).orElseThrow(()->new IllegalArgumentException("设备不存在"));String code=r.deviceCode().trim();devices.findByLicenseAndDeviceCode(d.getLicense(),code).filter(x->!x.getId().equals(id)).ifPresent(x->{throw new IllegalArgumentException("该设备码已绑定此卡密");});d.setDeviceCode(code);d.setDeviceName(r.deviceName());d.setEnabled(true);return devices.save(d);}
 @Transactional public void setDeviceEnabled(long id,boolean enabled){Device d=devices.findById(id).orElseThrow(()->new IllegalArgumentException("设备不存在"));d.setEnabled(enabled);devices.save(d);}
 public Map<String,Long> stats(){LocalDateTime now=LocalDateTime.now(),today=LocalDate.now().atStartOfDay();return Map.of("online",monitoredDevices.countByLastSeenAtAfterAndEnabledTrue(now.minusMinutes(2)),"todayLogins",sessions.countByLoginAtAfter(today),"todayUsers",monitoredDevices.countByLastSeenAtAfter(today),"todayDevices",monitoredDevices.countByFirstSeenAtAfter(today),"totalUsers",monitoredDevices.count(),"todayKeys",licenses.countByCreatedAtAfter(today),"totalKeys",licenses.count());}
 private boolean validationEnabled(){return runtimeConfigs.findById(1L).map(RuntimeConfig::isLicenseValidationEnabled).orElse(true);}
 private String uniqueCode(String prefix){String c;do{StringBuilder b=new StringBuilder(prefix);if(!prefix.isEmpty())b.append('-');for(int g=0;g<4;g++){if(g>0)b.append('-');for(int i=0;i<4;i++)b.append(CHARS[RNG.nextInt(CHARS.length)]);}c=b.toString();}while(licenses.findByCode(c).isPresent());return c;}
 private static String randomHex(int bytes){byte[] b=new byte[bytes];RNG.nextBytes(b);return HexFormat.of().formatHex(b);}
}